/bin/zsh -lc "docker compose exec app node -e '
const http = require(\"http\");
const crypto = require(\"crypto\");

const req = http.request({
  port: 9229,
  path: \"/27689437-869b-4692-a0d2-4a7af6b7facc\",
  headers: {
    \"Connection\": \"Upgrade\",
    \"Upgrade\": \"websocket\",
    \"Sec-WebSocket-Key\": crypto.randomBytes(16).toString(\"base64\"),
    \"Sec-WebSocket-Version\": \"13\"
  }
});

req.on(\"upgrade\", (res, socket) => {
  // send JSON-RPC command
  const msg = JSON.stringify({
    id: 1,
    method: \"Runtime.evaluate\",
    params: { expression: \"(() => { const st = require(\\\"./src/services/statements\\\"); return typeof st; })()\" }
  });
  const buf = Buffer.from(msg);
  const frame = Buffer.alloc(buf.length + 6);
  frame[0] = 0x81;
  frame[1] = 0x80 | buf.length; // assuming < 126
  frame.writeUInt32BE(0x12345678, 2);
  for (let i = 0; i < buf.length; i++) frame[6 + i] = buf[i] "'^ frame[2 + (i % 4)];
  socket.write(frame);

  socket.on("data", data => {
    console.log("Response:", data.toString("utf8", 2));
    socket.destroy();
  });
});
req.end();
'"'"

/bin/zsh -lc "docker compose exec app node -e '
const http = require(\"http\");
const crypto = require(\"crypto\");

http.get(\"http://127.0.0.1:9229/json\", res => {
  let d = \"\";
  res.on(\"data\", c => d += c);
  res.on(\"end\", () => {
    const list = JSON.parse(d);
    const id = list[0].id;
    const req = http.request({
      port: 9229,
      path: \"/\" + id,
      headers: {
        \"Connection\": \"Upgrade\",
        \"Upgrade\": \"websocket\",
        \"Sec-WebSocket-Key\": crypto.randomBytes(16).toString(\"base64\"),
        \"Sec-WebSocket-Version\": \"13\"
      }
    });
    req.on(\"upgrade\", (r, socket) => {
      const payload = JSON.stringify({
        id: 1,
        method: \"Runtime.evaluate\",
        params: { expression: \"process.memoryUsage()\" }
      });
      const pBuf = Buffer.from(payload);
      let header;
      if (pBuf.length < 126) {
        header = Buffer.alloc(6);
        header[0] = 0x81;
        header[1] = 0x80 | pBuf.length;
        header.writeUInt32BE(0x12345678, 2);
      } else {
        header = Buffer.alloc(8);
        header[0] = 0x81;
        header[1] = 0x80 | 126;
        header.writeUInt16BE(pBuf.length, 2);
        header.writeUInt32BE(0x12345678, 4);
      }
      const mask = header.slice(header.length - 4);
      const masked = Buffer.alloc(pBuf.length);
      for (let i = 0; i < pBuf.length; i++) masked[i] = pBuf[i] "'^ mask[i % 4];
      socket.write(Buffer.concat([header, masked]));

      socket.on("data", data => {
        console.log(data.toString("utf8"));
        socket.end();
      });
    });
    req.end();
  });
});
'"'"

