const http = require(\"http\");
const crypto = require(\"crypto\");

http.get(\"http://127.0.0.1:9229/json\", res => {
  let d = \"\";
  res.on(\"data\", c => d += c);
  res.on(\"end\", () => {
    const id = JSON.parse(d)[0].id;
    const req = http.request({
      port: 9229,
      path: \"/\" + id,
      headers: {
        \"Connection\": \"Upgrade\",
        \"Upgrade\": \"websocket\",
        \"Sec-WebSocket-Key\": crypto.randomBytes(16).toString(\"base64\"),
        \"Sec-WebSocket-Version\": \"13\"
      }
    });
    req.on(\"upgrade\", (r, socket) => {
      const expr = "'`(() => {
        const v8 = require("v8");
        return v8.writeHeapSnapshot("/app/heap.heapsnapshot");
      })()`;
      const payload = JSON.stringify({
        id: 1,
        method: "Runtime.evaluate",
        params: { expression: expr, returnByValue: true }
      });
      const pBuf = Buffer.from(payload);
      let header = Buffer.alloc(6);
      header[0] = 0x81;
      header[1] = 0x80 | pBuf.length;
      header.writeUInt32BE(0x12345678, 2);
      if (pBuf.length >= 126) {
        header = Buffer.alloc(8);
        header[0] = 0x81;
        header[1] = 0x80 | 126;
        header.writeUInt16BE(pBuf.length, 2);
        header.writeUInt32BE(0x12345678, 4);
      }
      const mask = header.slice(header.length - 4);
      const masked = Buffer.alloc(pBuf.length);
      for (let i = 0; i < pBuf.length; i++) masked[i] = pBuf[i] ''^ mask[i % 4];
      socket.write(Buffer.concat([header, masked]));

      socket.on("data", data => {
        console.log(data.toString("utf8"));
        socket.destroy();
        process.exit(0);
      });
    });
    req.end();
  });
});
'"'"

