      const pBuf = Buffer.from(payload);
      let header = Buffer.alloc(6);
      header[0] = 0x81;
      header[1] = 0x80 | pBuf.length;
      header.writeUInt32BE(0x12345678, 2);
      if (pBuf.length >= 126) {
        header = Buffer.alloc(8);
        header[0] = 0x81;
        header[1] = 0x80 | 126;
        header.writeUInt16BE(pBuf.length, 2);
        header.writeUInt32BE(0x12345678, 4);
      }
      const mask = header.slice(header.length - 4);
      const masked = Buffer.alloc(pBuf.length);
      for (let i = 0; i < pBuf.length; i++) masked[i] = pBuf[i] ^ mask[i % 4];
      socket.write(Buffer.concat([header, masked]));

      socket.on("data", data => {
        console.log(data.toString("utf8"));
        socket.destroy();
        process.exit(0);
      });
    });
    req.end();
  });
});
'"}

