{"cmd":"docker compose exec app node -e '
const { Worker, Queue } = require("bullmq");
const IORedis = require("ioredis");
const redis = new IORedis("redis://redis:6379");

async function test() {
  const q = new Queue("test-rl", { connection: redis });
  await q.drain();

  let processed = 0;
  let attempts = 0;
  let worker;
  worker = new Worker("test-rl", async (job) => {
    attempts++;
    console.log("Processing job", job.id, "attemptsMade:", job.attemptsMade, "total attempts:", attempts);
    if (processed < 2 && attempts === 2) {
      console.log("Rate limiting for 1000ms");
      await worker.rateLimit(1000);
      throw Worker.RateLimitError();
    }
    processed++;
    console.log("Job", job.id, "done. Total processed:", processed);
  }, { connection: redis, concurrency: 1 });

  await q.add("job", { num: 1 }, { attempts: 3 });
  await q.add("job", { num: 2 }, { attempts: 3 });

  await new Promise(r => setTimeout(r, 2500));
  console.log("Final processed:", processed, "total attempts:", attempts);
  await worker.close();
  await q.close();
  redis.disconnect();
}
test().catch(console.error);
'"}

