function postTransfer(fromId, toId, amount) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify({ fromId, toId, amount });
    const req = http.request({
      hostname: \"localhost\",
      port: 3000,
      path: \"/transfers\",
      method: \"POST\",
      headers: {
        \"Content-Type\": \"application/json\",
        \"Content-Length\": Buffer.byteLength(data),
      },
    }, (res) => {
      let body = \"\";
      res.on(\"data\", chunk => body += chunk);
      res.on(\"end\", () => resolve(JSON.parse(body)));
    });
    req.on(\"error\", reject);
    req.write(data);
    req.end();
  });
}

async function test() {
  const promises = [];
  for (let i = 0; i < 20; i++) {
    // 10 from 1 to 2, 10 from 2 to 1 in parallel
    promises.push(postTransfer(1, 2, 5));
    promises.push(postTransfer(2, 1, 5));
  }
  const results = await Promise.all(promises);
  console.log(\"Enqueued transfers:\", results.length);
  // Wait 2 seconds for processing
  await new Promise(r => setTimeout(r, 2000));
}

test().then(() => process.exit(0)).catch(err => { console.error(err); process.exit(1); });
'"

